                    FfiConverterTypeLinkStatus.lift(`status`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }
    internal object `onLoveLetter`: UniffiCallbackInterfaceLinkListenerMethod1 {
        override fun callback(`uniffiHandle`: Long,`letter`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeLinkListener.handleMap.get(uniffiHandle)
            val makeCall = { ->
