                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }
    internal object `onDriftChanged`: UniffiCallbackInterfaceLinkListenerMethod2 {
        override fun callback(`uniffiHandle`: Long,`driftVersion`: RustBuffer.ByValue,`driftReason`: RustBuffer.ByValue,`uniffiOutReturn`: Pointer,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeLinkListener.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`onDriftChanged`(
                    FfiConverterString.lift(`driftVersion`),
                    FfiConverterString.lift(`driftReason`),
                )
            }
            val writeReturn = { _: Unit -> Unit }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeLinkListener.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeLinkListener.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceLinkListener.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `onConnStatus`,
        `onLoveLetter`,
        `onDriftChanged`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_server_link_fn_init_callback_vtable_linklistener(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeLinkListener: FfiConverter<LinkListener, Long> {
    internal val handleMap = UniffiHandleMap<LinkListener>()

    override fun lower(value: LinkListener): Long {
        if (value is LinkListenerImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): LinkListener {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return LinkListenerImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): LinkListener {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: LinkListener) = 8UL

    override fun write(value: LinkListener, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}


