public interface ServerLinkInterface {
    
    /**
     * Tell the server this client has received letter `letter_id`.
     */
    suspend fun `ack`(`letterId`: kotlin.Long)
    
    /**
     * Ask the socket task to try opening a connection. Safe to call
     * often; extra signals are coalesced.
     */
    fun `attemptReconnect`()
    
    /**
     * Every page the server has. Used once by a client with no local pages.
     */
    suspend fun `getAllPages`(): List<PageSnapshot>
    
    /**
     * Reconcile ask: the server's drift version plus a fingerprint per page.
     * Exempt from the drift check, so a lonewolf client may call it.
     */
    suspend fun `getPageFingerprints`(): FingerprintsReply
    
    /**
     * Reconcile ask: full data of the named pages. Unknown ids are skipped.
     */
    suspend fun `getPagesByIds`(`pageIds`: List<kotlin.String>): List<PageSnapshot>
    
    /**
     * Reconcile ask: the current reconcile version.
     */
    suspend fun `getReconcileVersion`(): kotlin.String
    
    suspend fun `login`(`userName`: kotlin.String): LoginOutcome
    
    /**
     * Every letter the server still holds for this client, each stamped
     * with the drift version the server is on right now.
     */
    suspend fun `pullUnsentLetters`(): List<IncomingLetter>
    
    suspend fun `register`(`userName`: kotlin.String): RegisterOutcome
    
    /**
     * Send one already-encoded love letter and wait for the server's ok.
     */
    suspend fun `sendLoveLetter`(`loveLetter`: kotlin.ByteArray)
    
    /**
     * Reconcile ask: apply a batch of encoded love letters under the
     * claimed target versions. All or nothing on the server.
     */
    suspend fun `sendReconcileLetters`(`targetDriftVersion`: kotlin.String, `targetReconcileVersion`: kotlin.String, `letters`: List<kotlin.ByteArray>): ReconcileOutcome
    
    /**
     * Delete every page and letter on the server. The reply is the new
     * drift version the server entered; the caller adopts it.
     */
    suspend fun `wipeDataset`(): LoginInfo
    
    companion object
}

open class ServerLink: Disposable, AutoCloseable, ServerLinkInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_server_link_fn_free_serverlink(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_server_link_fn_clone_serverlink(handle, status)
        }
    }

    
    /**
     * Tell the server this client has received letter `letter_id`.
     */
    @Throws(LinkException::class)
    @Suppress("ASSIGNED_BUT_NEVER_ACCESSED_VARIABLE")
    override suspend fun `ack`(`letterId`: kotlin.Long) {
        return uniffiRustCallAsync(
        callWithHandle { uniffiHandle ->
