/**
 * @suppress
 */
public object FfiConverterTypeServerLink: FfiConverter<ServerLink, Long> {
    override fun lower(value: ServerLink): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): ServerLink {
        return ServerLink(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): ServerLink {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ServerLink) = 8UL

    override fun write(value: ServerLink, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



