/**
 * Every failure that crosses into Kotlin carries err_msg, method, file.
 *
 * - `Transport`: the socket isn't open or died before the reply came.
 * The row/letter was not confirmed; try again on the next kick.
 * - `Server`: the server answered with an error.
 * - `Local`: something on this side failed (decode, thread, platform).
 */
sealed class LinkException: kotlin.Exception() {
    
    class Transport(
        
        val `errMsg`: kotlin.String, 
        
        val `method`: kotlin.String, 
        
        val `file`: kotlin.String
        ) : LinkException() {
        override val message
            get() = "errMsg=${ `errMsg` }, method=${ `method` }, file=${ `file` }"
    }
    
    class Server(
        
        val `errMsg`: kotlin.String, 
        
        val `method`: kotlin.String, 
        
        val `file`: kotlin.String
        ) : LinkException() {
        override val message
            get() = "errMsg=${ `errMsg` }, method=${ `method` }, file=${ `file` }"
    }
    
    class Local(
        
        val `errMsg`: kotlin.String, 
        
        val `method`: kotlin.String, 
        
        val `file`: kotlin.String
        ) : LinkException() {
        override val message
            get() = "errMsg=${ `errMsg` }, method=${ `method` }, file=${ `file` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LinkException> {
        override fun lift(error_buf: RustBuffer.ByValue): LinkException = FfiConverterTypeLinkError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeLinkError : FfiConverterRustBuffer<LinkException> {
    override fun read(buf: ByteBuffer): LinkException {
        

        return when(buf.getInt()) {
            1 -> LinkException.Transport(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> LinkException.Server(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            3 -> LinkException.Local(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: LinkException): ULong {
        return when(value) {
            is LinkException.Transport -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errMsg`)
                + FfiConverterString.allocationSize(value.`method`)
                + FfiConverterString.allocationSize(value.`file`)
            )
            is LinkException.Server -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errMsg`)
                + FfiConverterString.allocationSize(value.`method`)
                + FfiConverterString.allocationSize(value.`file`)
            )
            is LinkException.Local -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`errMsg`)
                + FfiConverterString.allocationSize(value.`method`)
                + FfiConverterString.allocationSize(value.`file`)
            )
        }
    }

    override fun write(value: LinkException, buf: ByteBuffer) {
        when(value) {
            is LinkException.Transport -> {
                buf.putInt(1)
                FfiConverterString.write(value.`errMsg`, buf)
                FfiConverterString.write(value.`method`, buf)
                FfiConverterString.write(value.`file`, buf)
                Unit
            }
            is LinkException.Server -> {
                buf.putInt(2)
                FfiConverterString.write(value.`errMsg`, buf)
                FfiConverterString.write(value.`method`, buf)
                FfiConverterString.write(value.`file`, buf)
                Unit
            }
            is LinkException.Local -> {
                buf.putInt(3)
                FfiConverterString.write(value.`errMsg`, buf)
                FfiConverterString.write(value.`method`, buf)
                FfiConverterString.write(value.`file`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



